-- Yuqiao public empty schema. No accounts, sessions, media or API keys.
-- Import ONLY on a new machine with no existing yuqiao database.
CREATE DATABASE `yuqiao` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;
USE `yuqiao`;
CREATE TABLE users (id VARCHAR(64) PRIMARY KEY,username VARCHAR(128) NOT NULL UNIQUE,display_name TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,expires_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE records (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,kind VARCHAR(16) NOT NULL CHECK(kind IN ('text','video')),text LONGTEXT NOT NULL,media_file TEXT,mime TEXT,byte_length BIGINT NOT NULL DEFAULT 0,duration DOUBLE,created_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX records_user_time(user_id,created_at DESC)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE profiles (user_id VARCHAR(64) PRIMARY KEY,email TEXT,phone TEXT,avatar_file TEXT,avatar_mime TEXT,updated_at BIGINT NOT NULL,active_voice_id TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE voices (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,sample_file TEXT NOT NULL,ref_text LONGTEXT NOT NULL,name TEXT NOT NULL,note TEXT,duration DOUBLE NOT NULL,revision BIGINT NOT NULL DEFAULT 1,status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed')),created_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX voices_user_time(user_id,created_at DESC)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE practice_attempts (id VARCHAR(64) PRIMARY KEY,record_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('candidate','uncertain','unsupported','no_hands')),candidate_id TEXT,candidate_text TEXT,snapshot LONGTEXT NOT NULL,feedback VARCHAR(16) CHECK(feedback IN ('agree','disagree','uncertain')),correction VARCHAR(400) NOT NULL DEFAULT '',revision BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX practice_record_time(record_id,created_at DESC)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE sign_samples (record_id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,active INT NOT NULL DEFAULT 0,payload LONGTEXT,source_sha256 TEXT,revision BIGINT NOT NULL DEFAULT 0,updated_at BIGINT NOT NULL,FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX sign_samples_owner(user_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE sample_number_counters (user_id VARCHAR(64) NOT NULL,category VARCHAR(64) NOT NULL,last_number BIGINT NOT NULL,PRIMARY KEY(user_id,category),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE sample_numbers (record_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,category VARCHAR(64) NOT NULL,sequence BIGINT NOT NULL,PRIMARY KEY(record_id,category),UNIQUE(user_id,category,sequence),FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE video_save_keys (user_id VARCHAR(64) NOT NULL,save_key VARCHAR(128) NOT NULL,record_id VARCHAR(64),content_hash TEXT NOT NULL,request_hash TEXT NOT NULL,PRIMARY KEY(user_id,save_key),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
